	TIM2->CCMR[0]|=(1<<11);
	TIM2->CCMR[1]|=(1<<3);
	TIM2->CCER|=1<<8|1<<4;
	TIM2->CCR[2]=999;//ccr3
	//TIM2->CCR[1]=699;//ccr2
	TIM2->CR1|=1<<7;
	TIM2->EGR|=1;

	TIM2->CR1|=1;
