void control_step(uint8_t dir,uint8_t step,uint8_t en,uint8_t pin1,uint8_t pin2,uint8_t pin3)
{
	GPIO_WritePin(GPIOD,pin1,dir);
	GPIO_WritePin(GPIOD,pin3,en);
	for(int i=0;i<step*2;i++)
	{
		GPIO_TogglePin(GPIOD,pin2);
		for(int k=0;k<2000;k++);
	}
}
void control_step_x_y(uint8_t dir,uint8_t step,uint8_t en,uint8_t pin1,uint8_t pin2,uint8_t pin3,uint8_t dir1,uint8_t step1,uint8_t en1,uint8_t pin4,uint8_t pin5,uint8_t pin6)
{
	GPIO_WritePin(GPIOD,pin1,dir);
	GPIO_WritePin(GPIOD,pin3,en);
	GPIO_WritePin(GPIOD,pin4,dir1);
	GPIO_WritePin(GPIOD,pin6,en1);
	uint8_t stepx=step;
	if(step>step1) stepx=step1;
	for(int i=0;i<stepx*2;i++)
	{
		GPIO_TogglePin(GPIOD,pin2);
		GPIO_TogglePin(GPIOD,pin5);
		for(int k=0;k<2000;k++);
	}
	if(step<=step1)
	{
	for(int i=0;i<(step1-stepx)*2;i++)
	{
		GPIO_TogglePin(GPIOD,pin5);
		for(int k=0;k<2000;k++);
	}
	}
	else if(step1<step)
	{
		for(int i=0;i<(step-stepx)*2;i++)
		{
			GPIO_TogglePin(GPIOD,pin2);
			for(int k=0;k<2000;k++);
		}
	}
}
